# Original written exercises based on the user's theory note, PDF pages 18–19.
# Reuse existing name-recall items so equivalent definitions do not multiply.
security_concepts=[
('virus','바이러스','Virus','악성코드',19,'다른 실행 파일이나 부트 영역 등에 자신의 코드를 붙여 감염시키고 숙주가 실행될 때 함께 동작한다.','프로그램 파일에 악성 코드가 삽입되었다. 그 파일이 실행되면 악성 코드도 동작하고 다른 파일을 감염시킨다. 이 악성코드의 명칭을 쓰시오.','바이러스는 숙주 감염, 웜은 독립적인 자기 전파가 핵심입니다.',[]),
('worm','웜','Worm','악성코드',19,'다른 프로그램에 기생하지 않고 독립적으로 실행되며 네트워크 등을 통해 자신을 복제하고 전파한다.','취약한 장치를 통해 악성 프로그램이 스스로 다음 장치로 전파된다. 다른 실행 파일에 기생하지 않는 이 악성코드의 명칭을 쓰시오.','웜은 자기 전파, 트로이 목마는 정상 프로그램 위장이 핵심입니다.',[]),
('trojan','트로이 목마','Trojan Horse','악성코드',19,'정상적인 프로그램처럼 보이게 위장하여 사용자가 실행하도록 유도한다. 자기 복제는 일반적인 특징이 아니다.','무료 문서 변환기로 소개된 프로그램을 설치했더니 숨겨진 악성 기능이 실행되었다. 정상 프로그램으로 위장한 이 악성코드의 명칭을 쓰시오.','트로이 목마는 위장 실행입니다. 파일 감염·자기 전파와 구분하세요.',['트로이목마','Trojan']),
('ransomware','랜섬웨어','Ransomware','악성코드',19,'데이터를 암호화하거나 이용을 막은 뒤 복구를 대가로 금전을 요구한다.','회사 문서를 열 수 없게 되었고 화면에 복구 비용을 지급하라는 메시지가 나타났다. 해당 악성코드의 명칭을 쓰시오.','암호화·이용 방해 후 금전 요구가 핵심입니다.',[]),
('backdoor','백도어','Backdoor','악성코드',19,'정상적인 인증이나 접근 통제를 우회하여 시스템에 접근하도록 남겨 둔 숨은 통로이다.','공격자가 다시 들어올 수 있도록 정상 로그인 절차를 거치지 않는 비밀 접근 통로를 남겼다. 이 통로의 명칭을 쓰시오.','백도어는 우회 접근 통로입니다. 루트킷은 침해 흔적이나 악성 동작을 숨기는 도구 모음에 초점을 둡니다.',['Back Door']),
('rootkit','루트킷','Rootkit','악성코드',19,'침해된 시스템에서 권한 유지와 악성 활동의 은폐 등을 위해 사용하는 도구들의 모음이다.','침해 조사 중 악성 프로세스와 파일의 존재를 감추고 공격자의 권한 유지를 돕는 도구 모음이 발견되었다. 명칭을 쓰시오.','루트킷은 도구 모음과 은폐, 백도어는 우회 접근 통로입니다.',['루트 키트']),
('xss','XSS','Cross-Site Scripting','웹 공격',19,'웹 페이지에 주입한 스크립트가 방문자의 브라우저에서 실행되도록 하는 공격이다.','게시판 글에 삽입된 악성 스크립트가 그 글을 읽은 방문자의 브라우저에서 실행되었다. 공격 기법의 약어를 쓰시오.','XSS는 브라우저에서 스크립트 실행, CSRF는 인증된 사용자의 의도하지 않은 요청입니다.',['크로스 사이트 스크립팅','Cross Site Scripting']),
('csrf','CSRF','Cross-Site Request Forgery','웹 공격',19,'인증된 사용자가 자신의 의도와 다른 요청을 웹사이트에 보내도록 유도한다.','로그인 상태인 사용자가 외부 페이지를 방문하자 본인 의도와 달리 계정 정보 변경 요청이 원래 사이트로 전송되었다. 공격의 약어를 쓰시오.','이미 인증된 사용자의 권한을 이용한 요청 위조가 핵심입니다.',['크로스 사이트 요청 위조','Cross Site Request Forgery']),
('sql-injection','SQL 삽입','SQL Injection','웹 공격',19,'검증되지 않은 입력이 SQL 명령의 일부로 해석되어 데이터베이스 질의의 의미가 바뀌는 공격이다.','서버가 사용자 입력을 SQL 문자열에 직접 붙이고 있다. 조작된 입력으로 원래 질의의 조건이 바뀌어 비인가 데이터가 조회되었다. 공격 기법의 명칭을 쓰시오.','SQL 삽입은 서버의 데이터베이스 질의 조작입니다. XSS는 방문자 브라우저의 스크립트 실행입니다.',['SQL 삽입 공격','SQL 인젝션','SQL 주입']),
('dos','DoS','Denial of Service','네트워크 공격',18,'과도한 요청이나 취약점 악용 등으로 시스템이 정상적인 서비스를 제공하지 못하게 하는 공격이다.','하나의 공격원에서 요청을 집중시켜 서버 자원을 고갈시키고 정상 사용자의 접속을 방해했다. 서비스 거부 공격의 약어를 쓰시오.','DoS는 서비스 거부 공격의 통칭입니다. 여러 공격원에서 분산 수행하면 DDoS라고 합니다.',['서비스 거부 공격']),
('ddos','DDoS','Distributed Denial of Service','네트워크 공격',18,'여러 장치에서 동시에 하나의 서비스에 공격을 가하여 가용성을 방해하는 분산 서비스 거부 공격이다.','여러 지역의 감염된 장치들이 동시에 한 서버에 요청을 보내 정상 서비스를 마비시켰다. 공격의 약어를 쓰시오.','여러 공격원의 분산 수행이 DDoS의 구별 단서입니다.',['분산 서비스 거부 공격']),
('smurf','스머프','Smurf','네트워크 공격',18,'피해자 주소로 위장한 ICMP 요청을 브로드캐스트하여 다수의 응답이 피해자에게 집중되게 한다.','출발지 주소가 피해자로 위장된 ICMP 요청이 브로드캐스트되었고, 여러 장치의 응답이 피해자에게 몰렸다. 이 공격 기법을 쓰시오.','ICMP·브로드캐스트·응답 집중이 스머프의 핵심 단서입니다.',['스머핑','Smurfing','Smurf Attack']),
('land','랜드','LAND','네트워크 공격',18,'패킷의 출발지와 목적지 주소를 모두 공격 대상의 주소로 설정하는 공격이다.','비정상 패킷을 분석하니 출발지와 목적지 IP가 모두 피해 시스템의 IP로 설정되어 있었다. 공격 기법의 명칭을 쓰시오.','출발지와 목적지가 모두 피해자 주소라는 단서를 확인하세요.',['LAND Attack','랜드 공격']),
('teardrop','티어드롭','Teardrop','네트워크 공격',18,'조각난 IP 패킷의 오프셋 등 단편 정보를 비정상적으로 조작하여 재조립 처리를 방해한다.','비정상적으로 겹치는 단편 정보가 전달되어 IP 패킷의 재조립 과정에서 문제가 발생했다. 이 공격 기법의 명칭을 쓰시오.','단편화 정보와 재조립 오류가 핵심입니다.',['Tear Drop','TearDrop','티어 드롭']),
('syn-flooding','SYN 플러딩','SYN Flooding','네트워크 공격',18,'TCP 연결 설정을 끝내지 않는 요청을 대량으로 보내 반쯤 열린 연결 자원을 소모시킨다.','TCP 연결 요청이 대량으로 도착하지만 마지막 확인 응답이 오지 않아 미완료 연결이 쌓인다. 이 공격 기법을 쓰시오.','연결 설정 미완료 상태로 대기 자원을 소모하는 SYN 플러딩입니다.',['SYN Flood','SYN 플러딩 공격']),
('sniffing','스니핑','Sniffing','네트워크 공격',19,'네트워크에서 전달되는 패킷을 도청하여 통신 내용을 수집한다.','통신 상대방의 신원을 위장한 것이 아니라, 전송 중인 패킷을 엿보아 계정 정보를 수집했다. 이 행위의 명칭을 쓰시오.','스니핑은 엿보기, 스푸핑은 신원·주소 위장입니다.',[]),
('spoofing','스푸핑','Spoofing','네트워크 공격',19,'신뢰할 수 있는 다른 시스템이나 사용자처럼 주소·신원을 위장한다.','수신자가 신뢰하는 시스템에서 온 것처럼 보이도록 발신 주소를 위장했다. 이러한 공격의 일반적인 명칭을 쓰시오.','위장이 핵심입니다. 패킷을 수동적으로 엿보는 스니핑과 구분하세요.',[]),
('session-hijacking','세션 하이재킹','Session Hijacking','네트워크 공격',19,'정상 사용자의 세션 식별 정보 등을 가로채 그 사용자로 가장하여 연결을 이용한다.','공격자가 정상 사용자의 세션 정보를 탈취한 뒤 이미 인증된 사용자처럼 서비스를 이용했다. 공격 명칭을 쓰시오.','인증된 세션의 탈취·가로채기가 핵심입니다.',['세션 하이잭킹']),
('phishing','피싱','Phishing','정보 탈취',19,'신뢰할 만한 기관이나 사람을 사칭하여 민감한 정보를 제공하도록 속인다.','금융기관에서 보낸 것처럼 꾸민 이메일이 위조 로그인 페이지로 접속을 유도하며 계정 정보를 요구했다. 이 기법의 명칭을 쓰시오.','발신자·기관 사칭과 정보 제공 유도가 핵심입니다.',[]),
('smishing','스미싱','Smishing','정보 탈취',19,'문자 메시지를 이용하여 악성 링크 접속이나 앱 설치를 유도하고 정보를 탈취한다.','택배 배송 안내로 위장한 문자 메시지가 악성 링크 방문을 유도했다. 문자 메시지를 이용한 이 피싱 기법의 명칭을 쓰시오.','문자 메시지(SMS)가 스미싱의 구별 단서입니다.',[]),
('pharming','파밍','Pharming','정보 탈취',19,'이름 해석이나 호스트 설정 등을 조작하여 정상 주소로 접속하려는 사용자를 위조 사이트로 보낸다.','사용자는 올바른 은행 주소를 입력했지만 조작된 이름 해석 때문에 위조 사이트에 연결되었다. 이 기법의 명칭을 쓰시오.','파밍은 주소 해석·접속 경로 조작, 피싱은 사칭 메시지 등으로 정보를 유도하는 것이 핵심입니다.',[]),
('spear-phishing','스피어 피싱','Spear Phishing','정보 탈취',19,'특정 개인이나 조직을 표적으로 삼아 맞춤형 사칭 메시지로 정보를 탈취한다.','특정 회사의 담당 업무와 동료 이름을 조사한 뒤 해당 직원 한 명에게 맞춤형 사칭 이메일을 보냈다. 이 피싱 유형을 쓰시오.','불특정 다수보다 특정 표적에 맞춘 공격이라는 점이 핵심입니다.',['스피어피싱']),
('credential-stuffing','크리덴셜 스터핑','Credential Stuffing','정보 탈취',19,'다른 곳에서 유출된 계정·비밀번호 조합을 여러 서비스의 로그인에 재사용한다.','한 서비스에서 유출된 아이디와 비밀번호 조합들을 다른 서비스의 로그인에 그대로 대입했다. 이 공격 기법의 명칭을 쓰시오.','유출된 자격 증명의 재사용입니다. 가능한 모든 조합을 만드는 무차별 대입과 구분하세요.',['크리덴셜스터핑']),
('watering-hole','워터링 홀','Watering Hole','정보 탈취',19,'공격 대상이 자주 방문하는 웹사이트를 미리 침해하여 대상의 방문을 기다린다.','특정 조직 직원들이 자주 이용하는 업계 사이트를 먼저 감염시킨 후 그 직원들이 방문하기를 기다렸다. 이 공격의 명칭을 쓰시오.','대상이 자주 가는 사이트를 먼저 침해한다는 것이 단서입니다.',['워터링홀','Watering Hole Attack']),
]
def security_normalize(value):
 return ''.join(value.lower().replace('-',' ').split())
for key,name,en,group,page,description,scenario,contrast,other_aliases in security_concepts:
 concept='security-'+key
 aliases=list(dict.fromkeys([name,en,name+' 공격',en+' Attack']+other_aliases))
 FOCUS_CONCEPTS.append(dict(id=concept,topic='security',name=name,english=en,group=group,summary=description,contrast=contrast))
 existing=[]
 alias_keys={security_normalize(a) for a in aliases}
 for q in bank:
  if q['category']=='보안' and q['type']=='short' and security_normalize(q['answer']) in alias_keys:
   q.update(topic='security',concept=concept,exercise='description',patternGroup=group)
   q['aliases']=list(dict.fromkeys(q['aliases']+aliases));existing.append(q)
 if not existing:
  written('보안','short','다음 설명에 해당하는 악성코드 또는 공격 기법의 명칭을 쓰시오.\n\n'+description,name,contrast,page,2,aliases)
  bank[-1].update(topic='security',concept=concept,exercise='description',patternGroup=group)
 written('보안','short',scenario,name,contrast,page,2,aliases)
 bank[-1].update(topic='security',concept=concept,exercise='scenario',patternGroup=group)
comparisons=[
('virus','다른 파일에 기생하여 그 파일의 실행과 함께 동작한다. 독립적인 프로그램으로 네트워크에서 스스로 전파하는 웜과 구별되는 악성코드의 명칭을 쓰시오.'),
('worm','정상 실행 파일에 코드를 붙이는 방식이 아니라 독립적으로 복제·전파한다. 바이러스와 구별되는 이 악성코드의 명칭을 쓰시오.'),
('xss','두 공격을 구별하려 한다. 인증 상태로 다른 사이트에 요청을 보내게 하는 기법이 아니라, 삽입한 스크립트가 방문자 브라우저에서 실행되는 기법의 약어를 쓰시오.'),
('csrf','방문자의 브라우저에서 주입한 스크립트를 실행하는 것이 핵심이 아니라, 이미 로그인한 사용자의 권한으로 의도하지 않은 요청을 보내게 하는 공격의 약어를 쓰시오.'),
('sniffing','주소나 신원을 바꾸지 않고 전송되는 패킷을 엿보는 행위를 스푸핑과 구분하여 무엇이라고 하는가?'),
('spoofing','패킷을 엿보는 행위가 아니라 다른 시스템의 주소·신원인 것처럼 가장하는 행위를 무엇이라고 하는가?'),
('smishing','정보 탈취 시도에서 조작된 DNS가 아니라 SMS에 포함된 사칭 안내와 링크를 이용했다. 이 기법을 파밍과 구분하여 쓰시오.'),
('pharming','사용자는 주소를 올바르게 입력했으나 조작된 이름 해석으로 위조 사이트에 연결되었다. 문자 메시지를 이용한 스미싱과 구분되는 기법을 쓰시오.'),
('credential-stuffing','가능한 비밀번호를 전부 생성한 것이 아니라, 유출된 아이디·비밀번호 조합을 재활용하여 여러 사이트 로그인을 시도했다. 이 기법의 명칭을 쓰시오.'),
('ddos','서비스 거부라는 목적은 같지만 한 공격원이 아니라 여러 장치가 동시에 공격을 수행했다. DoS보다 구체적인 분산 공격의 약어를 쓰시오.'),
]
for key,prompt in comparisons:
 meta=next(c for c in FOCUS_CONCEPTS if c['id']=='security-'+key)
